import "strings"

func Sentence(sentence string) string {
    words := strings.Fields(sentence) // or split on spaces
    for i, w := range words {
        words[i] = translateWord(w)
    }
    return strings.Join(words, " ")
}

func isVowel(r rune) bool {
    switch r {
    case 'a', 'e', 'i', 'o', 'u':
        return true
    }
    return false
}

func translateWord(word string) string {
    if word == "" {
        return word
    }
    // Rule 1
    if isVowel(word[0]) || (len(word) >= 2 && (word[:2] == "xr" || word[:2] == "yt")) {
        return word + "ay"
    }
    // Find the index where the consonant cluster ends
    i := 1
    for i < len(word) && !isVowel(word[i]) {
        // Rule 3: qu
        if word[i] == 'q' && i+1 < len(word) && word[i+1] == 'u' {
            i += 2
            break
        }
        // Rule 4: y after consonants
        if i > 0 && word[i] == 'y' {
            break
        }
        i++
    }
    return word[i:] + word[:i] + "ay"
}
