package piglatin

import "strings"

// Sentence translates a sentence from English to Pig Latin.
func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, word := range words {
		words[i] = word(word)
	}
	return strings.Join(words, " ")
}

func isVowel(c byte) bool {
	switch c {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

// word translates a single word from English to Pig Latin.
func word(w string) string {
	if w == "" {
		return w
	}
	// Rule 1: word begins with a vowel, "xr", or "yt".
	if isVowel(w[0]) || (len(w) >= 2 && (w[:2] == "xr" || w[:2] == "yt")) {
		return w + "ay"
	}
	// Rules 2-4: find the end of the leading consonant cluster.
	i := 0
	for i < len(w) {
		if isVowel(w[i]) {
			break
		}
		// Rule 3: a "qu" is part of the consonant cluster.
		if w[i] == 'q' && i+1 < len(w) && w[i+1] == 'u' {
			i += 2
			break
		}
		// Rule 4: "y" acts as a vowel after a consonant cluster.
		if i > 0 && w[i] == 'y' {
			break
		}
		i++
	}
	return w[i:] + w[:i] + "ay"
}

